/**
 * Initial Catalog Data structured for Firestore per PRD Section 12.3
 */

function generateKeywords(name, category, material, tags = []) {
  const words = `${name} ${category} ${material} ${tags.join(' ')}`
    .toLowerCase()
    .replace(/[^\w\s]/g, '')
    .split(/\s+/)
    .filter(Boolean);
  return Array.from(new Set(words));
}

